# Grafana Alloy collection agent — one per host. Collects node metrics
# (incl. systemd unit states), cadvisor container metrics, journald and
# docker logs; ships to the monitoring stack on pylon (9091 remote_write,
# 3100 loki push). scope = "system" (NixOS hosts) | "user" (phanteks).
{
  mkSystemdService,
  pkgs,
  scope ? "system",
}:
{ config, lib, ... }:
let
  cfg = config.services.monitoring-agent;
  hostName = if scope == "system" then config.networking.hostName else "phanteks";
  storagePath = if scope == "system" then "/var/lib/alloy" else "/home/noah/.local/state/alloy";
  configFile = pkgs.writeText "config.alloy" ''
    prometheus.remote_write "central" {
      endpoint {
        url = "http://pylon:9091/api/v1/write"
      }
      external_labels = {
        host = "${hostName}",
      }
    }

    loki.write "central" {
      endpoint {
        url = "http://pylon:3100/loki/api/v1/push"
      }
    }

    prometheus.exporter.unix "node" {
      enable_collectors = ["systemd"]
    }

    prometheus.scrape "node" {
      targets    = prometheus.exporter.unix.node.targets
      forward_to = [prometheus.remote_write.central.receiver]
    }

    prometheus.exporter.cadvisor "containers" {
      docker_host = "unix:///var/run/docker.sock"
    }

    prometheus.scrape "containers" {
      targets    = prometheus.exporter.cadvisor.containers.targets
      forward_to = [prometheus.remote_write.central.receiver]
    }

    // journal comm=docker lines are dropped because compose-attached stacks
    // duplicate container stdout into the journal; transient scopes coalesced
    // to cap Loki stream churn.
    loki.relabel "journal" {
      forward_to = []
      rule {
        source_labels = ["__journal__comm"]
        regex         = "docker(-compose)?"
        action        = "drop"
      }
      rule {
        source_labels = ["__journal__systemd_unit"]
        target_label  = "unit"
      }
      rule {
        source_labels = ["unit"]
        regex         = "session-\\d+\\.scope"
        target_label  = "unit"
        replacement   = "session.scope"
      }
      rule {
        source_labels = ["unit"]
        regex         = "run-.+\\.(service|scope)"
        target_label  = "unit"
        replacement   = "run-transient"
      }
    }

    loki.source.journal "journal" {
      forward_to    = [loki.write.central.receiver]
      relabel_rules = loki.relabel.journal.rules
      labels        = {
        host   = "${hostName}",
        source = "journal",
      }
    }

    discovery.docker "containers" {
      host = "unix:///var/run/docker.sock"
    }

    discovery.relabel "docker" {
      targets = []
      rule {
        source_labels = ["__meta_docker_container_name"]
        regex         = "/(.*)"
        target_label  = "unit"
      }
    }

    loki.source.docker "docker" {
      host          = "unix:///var/run/docker.sock"
      targets       = discovery.docker.containers.targets
      relabel_rules = discovery.relabel.docker.rules
      forward_to    = [loki.write.central.receiver]
      labels        = {
        host   = "${hostName}",
        source = "docker",
      }
    }
  '';
in
{
  options.services.monitoring-agent.enable = lib.mkEnableOption "Grafana Alloy agent shipping metrics+logs to pylon";

  config = lib.mkIf cfg.enable (mkSystemdService {
    name = "monitoring-agent";
    inherit hostName scope;
    description = "Grafana Alloy collection agent";
    execStart = "${pkgs.grafana-alloy}/bin/alloy run --storage.path=${storagePath} ${configFile}";
    preStart = "${pkgs.coreutils}/bin/mkdir -p ${storagePath}";
    meta.hidden = true;

