813	      if (audio.currentTime / audio.duration > PREFETCH_TRIGGER_FRACTION) {
814	        tryStartPrefetch();
815	      }
816	
817	      const nowMs = Math.round(audio.currentTime * 1000);
818	      if (
819	        lastReportedMs < 0 ||
820	        Math.abs(nowMs - lastReportedMs) >= POSITION_REPORT_INTERVAL_MS
821	      ) {
822	        lastReportedMs = nowMs;
823	        const chapterId = ctx.dataset.chapterId;
824	        if (chapterId) {
825	          progress.observe({
826	            chapter_id: chapterId,
827	            audio_position_ms: nowMs,
828	          });
829	        }
830	      }
831	    });
832	
833	    // Play/pause icon — bound to the audio element's own state so it stays
834	    // in sync across morphdom patches (chapter swap re-renders #audio-player
835	    // and would otherwise reset the button text to the template default).
836	    ctx.bindElement(audio, ["play", "pause"], () => {
837	      playPauseBtn.textContent = audio.paused ? PLAY_GLYPH : PAUSE_GLYPH;
838	    });
839	
840	    // Side effects on play/pause that aren't DOM projection.
841	    ctx.on(audio, "play", () => {
842	      log("audio-play", {
843	        currentTime: audio.currentTime,
844	        duration: audio.duration,
845	      });
846	      scrollFollow.setPlaying(true);
847	      startHighlightLoop();
848	      if (ms) ms.playbackState = "playing";
849	      updateMediaSessionPosition();
850	    });
851	    ctx.on(audio, "pause", () => {
852	      log("audio-pause", {
853	        currentTime: audio.currentTime,
854	        duration: audio.duration,
855	        atEnd:
856	          Number.isFinite(audio.duration) &&
857	          audio.duration > 0 &&
858	          audio.currentTime >= audio.duration - 0.5,
859	      });
860	      scrollFollow.setPlaying(false);
861	      stopHighlightLoop();
862	      if (ms) ms.playbackState = "paused";
863	      const chapterId = ctx.dataset.chapterId;
864	      if (chapterId) {
865	        progress.observe({
866	          chapter_id: chapterId,
867	          audio_position_ms: Math.round(audio.currentTime * 1000),
868	        });
869	      }
870	    });
871	    ctx.on(audio, "ended", () => {
872	      log("audio-ended", {
873	        autoNext: readerSettings.get().autoNextChapter,
874	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
875	        prefetchInFlight: prefetchAbort !== null,
876	        prefetchedFor,
877	        nextUrl: ctx.dataset.nextAudioUrl ?? null,
878	      });
879	      stopHighlightLoop();
880	      if (readerSettings.get().autoNextChapter) {
881	        // JS-side chapter swap on the same <audio> element. This is the
882	        // critical path for sleeping-mobile autoplay: a full LV navigation
883	        // would tear down the OS audio session and silently fail when the
884	        // device is locked. Same-element src swap keeps the lock-screen
885	        // controls live and the audio session uninterrupted.
886	        goToNextChapter();
887	      }
888	    });
889	    ctx.on(audio, "error", () => {
890	      const err = audio.error;
891	      log("audio-error", {
892	        code: err?.code ?? null,
893	        message: err?.message ?? null,
894	        currentSrc: audio.currentSrc?.startsWith("blob:") ? "blob" : "url",
895	      });
896	    });
897	    ctx.on(audio, "stalled", () =>
898	      log("audio-stalled", { currentTime: audio.currentTime }),
899	    );
900	    ctx.on(audio, "waiting", () =>
901	      log("audio-waiting", { currentTime: audio.currentTime }),
902	    );
903	    ctx.on(audio, "loadedmetadata", () =>
904	      log("audio-loadedmetadata", { duration: audio.duration }),
905	    );
906	
907	    // Re-sync UX
908	    if (resyncBtn) {
909	      ctx.on(resyncBtn, "click", () => {
910	        scrollFollow.resume();
911	        if (currentWordIndex >= 0 && textContainer) {
912	          const el = textContainer.querySelector<HTMLElement>(
913	            wordSelector(currentWordIndex),
914	          );
915	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
916	        }
917	      });
918	    }
919	
920	    if (textContainer && "IntersectionObserver" in window) {
921	      intersectionObserver = new IntersectionObserver(
922	        (entries) => {
923	          for (const entry of entries) {
924	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
925	              scrollFollow.resume();
926	            }
927	          }
928	        },
929	        { threshold: 0.5 },
930	      );
931	      ctx.onDestroy(() => intersectionObserver?.disconnect());
932	    }
933	
934	    ctx.bindStore(scrollFollow, (s) => {
935	      if (!resyncBtn) return;
936	      resyncBtn.classList.toggle("hidden", !s.autoScrollPaused);
937	    });
938	
