968	      log("nav-prev-chapter-event");
969	      if (!goToPrevChapter()) ctx.pushEvent("prev_chapter", {});
970	    });
971	
972	    // Final cleanup not covered by ctx.on. Important: do NOT pause the
973	    // audio or revoke its current blob URL here. Destroy fires on LV
974	    // reconnect/re-mount (long phone sleep → server LV process times out
975	    // → client re-mount on wake) — and the <audio> element survives
976	    // (phx-update="ignore"). Pausing or revoking would interrupt the
977	    // user's listening session at exactly the moment they wake the phone
978	    // hoping playback continues. If the player is genuinely going away
979	    // (user navigates off the reader), the <audio> element gets removed
980	    // from the DOM, which auto-pauses it — no explicit pause needed.
