1	// Client-side durable buffer for reading-progress observations.
2	//
3	// The reader's persistence boundary used to be LiveView-only: every
4	// `audio_position` push went straight to the WS, with no fallback if the
5	// socket was suspended. On mobile, locking the screen suspends the WS but
6	// not the native audio session — so audio kept advancing while every
7	// position observation was silently dropped, and PC resume landed at a
8	// stale chapter.
9	//
10	// This module fixes that by giving every observation two delivery paths:
11	//   1. `pushEvent` over the WS (immediate, optimistic)
12	//   2. `navigator.sendBeacon` to /api/books/:id/progress
13	//      (fired on visibilitychange:hidden + pagehide)
14	//
15	// Both transports converge on `ReadaloudReader.observe!/1`, which is
16	// idempotent under replay (stale-drop by `observed_at`). So sending the
17	// same observation twice is harmless. The buffer's job is to make sure
18	// every observation hits *at least one* of the two paths.
19	//
20	// Storage: a small bounded queue in localStorage keyed by bookId. Entries
21	// older than 60s are pruned on every observe — they're either already
22	// delivered (WS happy path) or no longer worth resending (server has
23	// fresher state from in-flight ticks).
24	
25	import { type JsonValue, isJsonObject, parseJson } from "./types";
26	
27	export interface ProgressObservation {
28	  readonly chapter_id: string;
29	  readonly audio_position_ms?: number;
30	  readonly scroll_position?: number;
31	  readonly observed_at: string;
32	}
33	
34	export interface ProgressBuffer {
35	  observe(obs: Omit<ProgressObservation, "observed_at">): void;
36	  detach(): void;
37	}
38	
39	interface ProgressBufferDeps {
40	  readonly bookId: number;
41	  readonly beaconUrl: string;
42	  readonly pushObservations: (
43	    observations: ReadonlyArray<ProgressObservation>,
44	  ) => void;
45	}
46	
47	const STORAGE_KEY_PREFIX = "readaloud-progress-buffer:";
48	const MAX_BUFFER_ENTRIES = 50;
49	const BACKLOG_PRUNE_AGE_MS = 60_000;
50	
51	function storageKey(bookId: number): string {
52	  return `${STORAGE_KEY_PREFIX}${bookId}`;
53	}
54	
55	function parseObservation(v: JsonValue): ProgressObservation | null {
56	  if (!isJsonObject(v)) return null;
57	  if (typeof v.chapter_id !== "string") return null;
58	  if (typeof v.observed_at !== "string") return null;
59	  const out: {
60	    -readonly [K in keyof ProgressObservation]: ProgressObservation[K];
61	  } = {
62	    chapter_id: v.chapter_id,
63	    observed_at: v.observed_at,
64	  };
65	  if (typeof v.audio_position_ms === "number") {
66	    out.audio_position_ms = v.audio_position_ms;
67	  }
68	  if (typeof v.scroll_position === "number") {
69	    out.scroll_position = v.scroll_position;
70	  }
71	  return out;
72	}
73	
74	function readBacklog(bookId: number): ReadonlyArray<ProgressObservation> {
75	  const raw = localStorage.getItem(storageKey(bookId));
76	  if (!raw) return [];
77	  try {
78	    const json = parseJson(raw);
79	    if (!Array.isArray(json)) return [];
80	    const out: ProgressObservation[] = [];
81	    for (const entry of json) {
82	      const obs = parseObservation(entry);
83	      if (obs) out.push(obs);
84	    }
85	    return out;
86	  } catch {
87	    return [];
88	  }
89	}
90	
91	function writeBacklog(
92	  bookId: number,
93	  backlog: ReadonlyArray<ProgressObservation>,
94	): void {
95	  if (backlog.length === 0) {
96	    localStorage.removeItem(storageKey(bookId));
97	    return;
98	  }
99	  localStorage.setItem(storageKey(bookId), JSON.stringify(backlog));
100	}
101	
102	function pruneBacklog(
103	  backlog: ReadonlyArray<ProgressObservation>,
104	  now: number,
105	): ReadonlyArray<ProgressObservation> {
106	  const cutoff = now - BACKLOG_PRUNE_AGE_MS;
107	  const fresh = backlog.filter((entry) => {
108	    const ts = Date.parse(entry.observed_at);
109	    return Number.isFinite(ts) && ts >= cutoff;
110	  });
111	  if (fresh.length <= MAX_BUFFER_ENTRIES) return fresh;
112	  // Keep the most recent MAX_BUFFER_ENTRIES — observed_at is monotonic
113	  // for fresh inserts, so the tail is what we want.
114	  return fresh.slice(-MAX_BUFFER_ENTRIES);
115	}
116	
117	export function attachProgressBuffer(deps: ProgressBufferDeps): ProgressBuffer {
118	  const { bookId, beaconUrl, pushObservations } = deps;
119	
120	  // Replay anything still in localStorage from a prior mount or unload.
121	  // Prune first — if the user force-killed the tab N days ago, the same
122	  // stale entry would otherwise re-fire on every mount forever (server
123	  // stale-drops it, but that's bytes wasted on every page load). Persist
124	  // the pruned form back so the cleanup survives even if no observation
125	  // happens this mount.
126	  const initial = pruneBacklog(readBacklog(bookId), Date.now());
127	  writeBacklog(bookId, initial);
128	  if (initial.length > 0) {
129	    try {
130	      pushObservations(initial);
131	    } catch {
132	      // pushEvent shouldn't throw; if it does, sendBeacon still owns the
133	      // durable path and we fall back on next visibilitychange.
134	    }
135	  }
136	
137	  function append(obs: ProgressObservation): void {
138	    const now = Date.now();
139	    const merged = pruneBacklog([...readBacklog(bookId), obs], now);
140	    writeBacklog(bookId, merged);
141	  }
142	
143	  function flushViaBeacon(): void {
144	    const backlog = readBacklog(bookId);
145	    if (backlog.length === 0) return;
146	    if (typeof navigator === "undefined" || !navigator.sendBeacon) return;
147	    const body = new Blob([JSON.stringify({ observations: backlog })], {
148	      type: "application/json",
149	    });
150	    const accepted = navigator.sendBeacon(beaconUrl, body);
151	    if (accepted) {
152	      // sendBeacon's "accepted" only means the browser queued the request,
153	      // not that the server received it. But the request has the same
154	      // observation payload the server's idempotent `observe!/1` already
155	      // tolerates as a duplicate, so clearing locally is safe — even if
156	      // the beacon fails, the next observe will re-seed the buffer.
157	      writeBacklog(bookId, []);
158	    }
159	  }
160	
