1	import type { LiveViewHookSpec, ViewHookInternal } from "phoenix_live_view";
2	import type {
3	  ReadaloudHandleEvents,
4	  ReadaloudPushEvents,
5	  ReadaloudWindowEvents,
6	} from "./events";
7	import type { ReadableStore } from "./store";
8	
9	type EmptyPayload = undefined | Record<string, never>;
10	
11	type WindowEventDetail<K extends keyof ReadaloudWindowEvents> =
12	  ReadaloudWindowEvents[K] extends undefined
13	    ? []
14	    : [detail: ReadaloudWindowEvents[K]];
15	
16	type PushEventArgs<K extends keyof ReadaloudPushEvents> =
17	  ReadaloudPushEvents[K] extends EmptyPayload
18	    ? []
19	    : [payload: ReadaloudPushEvents[K]];
20	
21	export interface HookContext<
22	  TEl extends HTMLElement = HTMLElement,
23	  TDataset = Record<string, string | undefined>,
24	> {
25	  readonly el: TEl;
26	  readonly dataset: Readonly<TDataset>;
27	
28	  on<K extends keyof HTMLElementEventMap>(
29	    target: HTMLElement | Document,
30	    event: K,
31	    handler: (e: HTMLElementEventMap[K]) => void,
32	    opts?: AddEventListenerOptions,
33	  ): void;
34	  on<K extends keyof WindowEventMap>(
35	    target: Window,
36	    event: K,
37	    handler: (e: WindowEventMap[K]) => void,
38	    opts?: AddEventListenerOptions,
39	  ): void;
40	  on<K extends keyof ReadaloudWindowEvents>(
41	    target: Window,
42	    event: K,
43	    handler: ReadaloudWindowEvents[K] extends undefined
44	      ? () => void
45	      : (detail: ReadaloudWindowEvents[K]) => void,
46	  ): void;
47	
48	  dispatch<K extends keyof ReadaloudWindowEvents>(
49	    event: K,
50	    ...detail: WindowEventDetail<K>
51	  ): void;
52	
53	  pushEvent<K extends keyof ReadaloudPushEvents>(
54	    event: K,
55	    ...payload: PushEventArgs<K>
56	  ): void;
57	
58	  handleEvent<K extends keyof ReadaloudHandleEvents>(
59	    event: K,
60	    handler: (payload: ReadaloudHandleEvents[K]) => void,
61	  ): void;
62	
63	  onDestroy(fn: () => void): void;
64	  onUpdate(fn: () => void): void;
65	
66	  // Bind a DOM projection to a subscribable store. Runs apply once with the
67	  // current snapshot, re-runs on every store change, and re-runs on every
68	  // LiveView update so morphdom can't desync the DOM from the truth.
69	  bindStore<T>(store: ReadableStore<T>, apply: (snapshot: T) => void): void;
70	
71	  // Bind a DOM projection to one or more events on an element. Runs apply
72	  // once now, then on every listed event, then on every LiveView update.
73	  // Use when the source of truth lives on the element itself (e.g. an
74	  // <audio>'s paused state) rather than in a store.
75	  //
76	  // K is constrained to keyof HTMLElementEventMap rather than something
77	  // narrower per element-subtype because TypeScript's lib.dom.d.ts puts
78	  // every media event on every HTMLElement via GlobalEventHandlersEventMap
79	  // (the legacy `onplay`/`onpause` mixin). Tightening this further would
80	  // require shadowing lib.dom.d.ts — not worth it. Misuse fails silently
81	  // (DOM no-ops on a wrong-target listener); we accept this trade-off.
82	  bindElement<K extends keyof HTMLElementEventMap>(
83	    target: HTMLElement,
84	    events: readonly K[],
85	    apply: () => void,
86	  ): void;
87	}
88	
89	const READALOUD_EVENT_PREFIX_RE =
90	  /^(audio:|manual-scroll$|auto-scroll-|word-action$|toggle-pill$|chapter-bar-close$|readaloud:|phx:)/;
91	
92	function isReadaloudEvent(event: string): boolean {
93	  return READALOUD_EVENT_PREFIX_RE.test(event);
94	}
95	
96	interface HookState {
97	  readonly disposers: Array<() => void>;
98	  readonly updateHandlers: Array<() => void>;
99	}
100	
101	// Per-mount state, keyed off the LV view-hook `this`. WeakMap avoids
102	// bolting expando fields onto ViewHookInternal (which would force a cast
103	// at every read site to satisfy TS).
104	const HOOK_STATE = new WeakMap<ViewHookInternal, HookState>();
105	
106	export function defineHook<
107	  TEl extends HTMLElement = HTMLElement,
108	  TDataset = Record<string, string | undefined>,
109	>(setup: (ctx: HookContext<TEl, TDataset>) => void): LiveViewHookSpec {
110	  return {
111	    mounted(this: ViewHookInternal): void {
112	      const disposers: Array<() => void> = [];
113	      const updateHandlers: Array<() => void> = [];
114	      const lv = this;
115	
116	      const ctx: HookContext<TEl, TDataset> = {
117	        // The LV markup is the source of truth for the element subtype and
118	        // the dataset shape. TS can't verify this contract; the caller of
119	        // defineHook<TEl, TDataset> asserts it.
120	        // ast-grep-ignore: no-as-cast
121	        el: this.el as TEl,
122	        // ast-grep-ignore
123	        dataset: this.el.dataset as unknown as Readonly<TDataset>,
124	
125	        on(
126	          target: EventTarget,
127	          event: string,
128	          // Impl signature for the typed overloads above. Callers see the
129	          // narrowed handler types; the impl must accept the union, which
130	          // TS only expresses as `unknown`.
131	          // ast-grep-ignore: no-unknown-type
132	          handler: (arg: unknown) => void,
133	          opts?: AddEventListenerOptions,
134	        ): void {
135	          if (target === window && isReadaloudEvent(event)) {
136	            const wrapped = (e: Event): void => {
137	              if (e instanceof CustomEvent) handler(e.detail);
138	            };
139	            window.addEventListener(event, wrapped);
140	            disposers.push(() => window.removeEventListener(event, wrapped));
141	          } else {
142	            // The DOM API only knows EventListener, not our typed overloads.
143	            // ast-grep-ignore: no-as-cast
144	            target.addEventListener(event, handler as EventListener, opts);
145	            disposers.push(() =>
146	              // ast-grep-ignore: no-as-cast
147	              target.removeEventListener(event, handler as EventListener, opts),
148	            );
149	          }
150	        },
151	
152	        // ast-grep-ignore: no-unknown-type
153	        dispatch(event: string, detail?: unknown): void {
154	          window.dispatchEvent(new CustomEvent(event, { detail }));
155	        },
156	
157	        pushEvent(event: string, payload?: object): void {
158	          lv.pushEvent(event, payload ?? {});
159	        },
160	
161	        handleEvent(event: string, handler: (payload: never) => void): void {
162	          // Phoenix's typed shim wants `(payload: unknown) => void`. Our
163	          // public overload above narrows the payload per event K; the
164	          // impl signature uses `never` for parametric assignability and
165	          // we re-widen here to satisfy the LV type.
166	          // ast-grep-ignore
167	          const ref = lv.handleEvent(event, handler as (p: unknown) => void);
168	          disposers.push(() => lv.removeHandleEvent(ref));
169	        },
170	
171	        onDestroy(fn: () => void): void {
172	          disposers.push(fn);
173	        },
174	
175	        onUpdate(fn: () => void): void {
176	          updateHandlers.push(fn);
177	        },
178	
