1	// Client-side durable buffer for audio-player diagnostic events.
2	//
3	// Same delivery architecture as progress_buffer (which owns reading
4	// *position*; this owns playback *diagnostics*): every event gets two
5	// paths to the server —
6	//   1. `pushEvent("player_events")` over the WS (immediate, optimistic)
7	//   2. `navigator.sendBeacon` to /api/books/:id/player-events, fired on
8	//      visibility transitions + pagehide
9	//
10	// The whole point of this channel is forensics for the sleeping-mobile
11	// autoplay bugs: when the screen locks, the WS suspends but the audio
12	// session (and this hook's event handlers) keep running. Events recorded
13	// while the socket is dead sit in localStorage and drain via beacon on the
14	// next visibility transition, or via WS replay on the next mount.
15	//
16	// Unlike progress observations, events are NOT idempotent server-side —
17	// a re-delivered event double-counts in Prometheus. We accept that: the
18	// prune window is short, the server treats counter rates as approximate,
19	// and every log line carries the client `at` timestamp so duplicates are
20	// trivially identifiable in Loki. Losing the last events before a phone
21	// slept would cost far more than a few duplicate counts.
22	
23	import type { PlayerEventDetailValue, PlayerEventPayload } from "./events";
24	import { isJsonObject, type JsonValue, parseJson } from "./types";
25	
26	export interface PlayerEventBuffer {
27	  record(
28	    event: string,
29	    fields?: {
30	      readonly chapter_id?: string;
31	      readonly position_ms?: number;
32	      readonly detail?: Readonly<Record<string, PlayerEventDetailValue>>;
33	    },
34	  ): void;
35	  detach(): void;
36	}
37	
38	interface PlayerEventBufferDeps {
39	  readonly bookId: number;
40	  readonly beaconUrl: string;
41	  readonly pushEvents: (events: ReadonlyArray<PlayerEventPayload>) => void;
42	}
43	
44	const STORAGE_KEY_PREFIX = "readaloud-player-events:";
45	const MAX_BUFFER_ENTRIES = 100;
46	const BACKLOG_PRUNE_AGE_MS = 120_000;
47	
48	function storageKey(bookId: number): string {
49	  return `${STORAGE_KEY_PREFIX}${bookId}`;
50	}
51	
52	function isDetailValue(v: JsonValue | undefined): v is PlayerEventDetailValue {
53	  return (
54	    v === null ||
55	    typeof v === "string" ||
56	    typeof v === "number" ||
57	    typeof v === "boolean"
58	  );
59	}
60	
61	function parseEvent(v: JsonValue): PlayerEventPayload | null {
62	  if (!isJsonObject(v)) return null;
63	  if (typeof v.event !== "string") return null;
64	  if (typeof v.at !== "string") return null;
65	  const out: {
66	    -readonly [K in keyof PlayerEventPayload]: PlayerEventPayload[K];
67	  } = { event: v.event, at: v.at };
68	  if (typeof v.chapter_id === "string") out.chapter_id = v.chapter_id;
69	  if (typeof v.position_ms === "number") out.position_ms = v.position_ms;
70	  if (v.detail !== undefined && isJsonObject(v.detail)) {
71	    const detail: Record<string, PlayerEventDetailValue> = {};
72	    for (const [key, value] of Object.entries(v.detail)) {
73	      if (isDetailValue(value)) detail[key] = value;
74	    }
75	    out.detail = detail;
76	  }
77	  return out;
78	}
79	
80	function readBacklog(bookId: number): ReadonlyArray<PlayerEventPayload> {
81	  const raw = localStorage.getItem(storageKey(bookId));
82	  if (!raw) return [];
83	  try {
84	    const json = parseJson(raw);
85	    if (!Array.isArray(json)) return [];
86	    const out: PlayerEventPayload[] = [];
87	    for (const entry of json) {
88	      const event = parseEvent(entry);
89	      if (event) out.push(event);
90	    }
91	    return out;
92	  } catch {
93	    return [];
94	  }
95	}
96	
97	function writeBacklog(
98	  bookId: number,
99	  backlog: ReadonlyArray<PlayerEventPayload>,
100	): void {
101	  if (backlog.length === 0) {
102	    localStorage.removeItem(storageKey(bookId));
103	    return;
104	  }
105	  localStorage.setItem(storageKey(bookId), JSON.stringify(backlog));
106	}
107	
108	function pruneBacklog(
109	  backlog: ReadonlyArray<PlayerEventPayload>,
110	  now: number,
111	): ReadonlyArray<PlayerEventPayload> {
112	  const cutoff = now - BACKLOG_PRUNE_AGE_MS;
113	  const fresh = backlog.filter((entry) => {
114	    const ts = Date.parse(entry.at);
115	    return Number.isFinite(ts) && ts >= cutoff;
116	  });
117	  if (fresh.length <= MAX_BUFFER_ENTRIES) return fresh;
118	  return fresh.slice(-MAX_BUFFER_ENTRIES);
119	}
120	
121	export function attachPlayerEventBuffer(
122	  deps: PlayerEventBufferDeps,
123	): PlayerEventBuffer {
124	  const { bookId, beaconUrl, pushEvents } = deps;
125	
126	  // Replay anything still buffered from a prior mount or unload — this is
127	  // how events recorded while a locked phone's WS was dead reach the
128	  // server after the LV re-mounts on wake.
129	  const initial = pruneBacklog(readBacklog(bookId), Date.now());
130	  writeBacklog(bookId, initial);
131	  if (initial.length > 0) {
132	    try {
133	      pushEvents(initial);
134	    } catch {
135	      // pushEvent shouldn't throw; if it does, the beacon path still owns
136	      // durability on the next visibility transition.
137	    }
138	  }
139	
140	  function append(event: PlayerEventPayload): void {
141	    const merged = pruneBacklog([...readBacklog(bookId), event], Date.now());
142	    writeBacklog(bookId, merged);
143	  }
144	
145	  function flushViaBeacon(): void {
146	    const backlog = readBacklog(bookId);
147	    if (backlog.length === 0) return;
148	    if (typeof navigator === "undefined" || !navigator.sendBeacon) return;
149	    const body = new Blob([JSON.stringify({ events: backlog })], {
150	      type: "application/json",
151	    });
152	    if (navigator.sendBeacon(beaconUrl, body)) {
153	      writeBacklog(bookId, []);
154	    }
155	  }
156	
157	  // Flush on BOTH visibility transitions: `hidden` is the canonical
158	  // last-chance moment, and `visible` drains anything recorded while the
159	  // screen was locked without waiting for the WS to re-establish.
160	  function onVisibilityChange(): void {
161	    flushViaBeacon();
162	  }
163	
164	  document.addEventListener("visibilitychange", onVisibilityChange);
165	  window.addEventListener("pagehide", flushViaBeacon);
166	
167	  return {
168	    record(event, fields) {
169	      const payload: PlayerEventPayload = {
170	        event,
171	        at: new Date().toISOString(),
172	        ...fields,
173	      };
174	      append(payload);
175	      try {
176	        pushEvents([payload]);
177	      } catch {
178	        // Same fallback rationale as the initial replay above.
179	      }
180	    },
181	    detach() {
182	      document.removeEventListener("visibilitychange", onVisibilityChange);
183	      window.removeEventListener("pagehide", flushViaBeacon);
184	    },
185	  };
186	}

